@startuml

class Game {
  + hiddenTile : Tile
}

class Board {
  + layout : string
}

class Tile {
  + color : string
  + isActionTile : boolean
  + actionTurnsRemaining : int
}

class Connection {
  + side : string
}

class ActionCard {
  + type : ActionType
}

enum ActionType {
  ROLL_EXTRA_TURN
  CONNECT_ADJACENT_TILES
  REMOVE_CONNECTION
  MOVE_TO_ARBITRARY_TILE
  LOSE_NEXT_TURN
}

class Player {
  + color : string
  + isStartingPosition : boolean
}

class PlayingPiece {
  + color : string
}

class Die {
}

class Designer {}

class PlayerInstance {
  + turnOrder : int
}

Designer "1" -- "*" Game : designs
Game "1" *-- "1" Board
Board "1" *-- "*" Tile
Board "1" *-- "*" Connection
Tile "1" -- "0..4" Connection : connects to
Game "1" *-- "32" ActionCard
Game "1" -- "2..4" PlayerInstance
PlayerInstance "1" -- "1" Player : is
PlayerInstance "1" -- "1" PlayingPiece
Game "1" -- "1" Die : uses

@enduml

